class Box
{
public:
      double getVolume(void)
{
return length * breadth * height;
      }
private:
      double length;      // 长度
double breadth;     // 宽度
double height;      // 高度
};

#include <iostream>
using namespace std;

class Adder{
public:
      // 构造函数
Adder(int i = 0)
{
total = i;
      }
// 对外的接口
void addNum(int number)
{
total += number;
      }
// 对外的接口
int getTotal()
{
return total;
      };
   private:
      // 对外隐藏的数据
int total;
};
int main( )
{
Adder a;

   a.addNum(10);
   a.addNum(20);
   a.addNum(30);

   cout << "Total " << a.getTotal() <<endl;
   return 0;
}

#include <iostream>
using namespace std;

class Student {
private:
    string name;
    int age;

public:
    // 构造函数
    Student(string studentName, int studentAge) {
        name = studentName;
        age = studentAge;
    }

    // 访问器函数（getter）
    string getName() {
        return name;
    }

    int getAge() {
        return age;
    }

    // 修改器函数（setter）
    void setName(string studentName) {
        name = studentName;
    }

    void setAge(int studentAge) {
        if (studentAge > 0) {
            age = studentAge;
        } else {
            cout << "Invalid age!" << endl;
        }
    }

    // 打印学生信息
    void printInfo() {
        cout << "Name: " << name << ", Age: " << age << endl;
    }
};

int main() {
    // 创建一个 Student 对象
    Student student1("Alice", 20);

    // 访问和修改数据
    student1.printInfo();

    student1.setName("Bob");
    student1.setAge(22);

    student1.printInfo();

    return 0;
}
